/*
 * A088205  Infinite audioactive word that shifts 1 place left under "Look and
 *          Say" method A, starting with a(0)=0.
 * https://oeis.org/A088205
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn
 * Formula:   a(n) is generated by iteratively appending the * run‑length
 *            encoding of the current word. The sequence * starts with 0 and
 *            each subsequent run of equal values * produces two new terms:
 *            the count of the run and the value
 * Range:     u8 n <= 104, u16 n <= 104, u32 n <= 104, u64 n <= 104,
 *            u128 n <= 104, big any n
 * Helpers:   alloc_cache, free_cache
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>
#include <stddef.h>
#include "../utils/alloc_cache.h"
#include "../utils/free_cache.h"

/* Computes a(n) for A088205 */
seq_t a(idx_t n)
{
    /* Slow-moving state: the growing word, its size, and the
     * index of the next run to process. */
    static seq_t *buf = NULL;
    static size_t cap   = 0;
    static size_t len   = 0;
    static idx_t processed = 0;

    /* initialise on first call */
    if (!buf) {
        cap   = 16;
        buf   = alloc_cache(cap);
        if (!buf) abort();
        buf[0] = (seq_t)0;   /* a(0) */
        len   = 1;
        processed = 0;
    }

    /* grow the word until it contains at least n+1 terms */
    while (len <= n) {
        /* ensure space for the two terms that will be appended */
        if (len + 2 > cap) {
            size_t new_cap = cap * 2;
            seq_t *tmp = alloc_cache(new_cap);
            if (!tmp) abort();
            for (size_t i = 0; i < len; ++i) tmp[i] = buf[i];
            free_cache(buf);
            buf = tmp;
            cap = new_cap;
        }

        /* process the next run in the current word */
        idx_t start = processed;
        seq_t val   = buf[start];
        idx_t run_len = 1;
        while (start + run_len < len && buf[start + run_len] == val)
            ++run_len;

        /* append the run length and the value */
        buf[len++] = (seq_t)run_len;
        buf[len++] = val;

        processed = start + run_len;
    }

    return buf[n];
}
